=== EarthCascade
public class EarthCascade : Projectile
private Collider2D[] colliders;
private int releaseStopwatchID = -1;
private float releaseDelay;
private float releaseMoveSpeed = 1f;
private bool released;
get
if (_shootEffectOverride == null)
ParticleSystemOverride particleSystemOverride = new ParticleSystemOverride();
particleSystemOverride.startColor = new Color(1f, 1f, 1f, 0.25f);
particleSystemOverride.startLifetime = 0.15f;
_shootEffectOverride = particleSystemOverride;
return _shootEffectOverride;
public static GameObject Prefab => prefab ?? (prefab = ChaosBundle.Get("Assets/Prefabs/Projectiles/EarthCascade.prefab"));
public override void Awake()
base.Awake();
colliders = GetComponentsInChildren<Collider2D>();
EnableColliders(status: false);
releaseMoveSpeed = moveSpeed;
public override void Start()
base.Start();
moveSpeed = 0f;
if (releaseDelay > 0f)
releaseStopwatchID = ChaosStopwatch.Begin(releaseDelay);
public override void Update()
if (!released)
if (!ChaosStopwatch.Check(releaseStopwatchID))
return;
released = true;
RockBurstDirectionalEffect poolItem = PoolManager.GetPoolItem<RockBurstDirectionalEffect>("RockBurstDirectionalEffect");
RockDebrisType debrisType = RockDebrisType.Dark;
int? particleCount = 1;
Vector3? position = transform.position;
Vector3? localEulerAngles = Globals.GetRotationVector(moveVector);
poolItem.EmitSingle(debrisType, particleCount, position, null, localEulerAngles);
ReleaseProjectile();
base.Update();
public override void ResetProjectile()
base.ResetProjectile();
PoolManager.GetPoolItem<RockBurstDirectionalEffect>("RockBurstDirectionalEffect").EmitSingle(RockDebrisType.Dark, 1, transform.position);
public void SetReleaseVars(Vector2 givenVector, float givenDelay = 0f)
moveVector = givenVector;
if (givenDelay > 0f)
releaseDelay = givenDelay;
private void ReleaseProjectile()
InitTimers();
moveSpeed = releaseMoveSpeed;
EnableColliders();
SoundManager.PlayAudioWithDistance("EarthDust", transform.position);
private void EnableColliders(bool status = true)
Collider2D[] array = colliders;
foreach (Collider2D collider2D in array)
collider2D.enabled = status;
=== EarthClap
public class EarthClap : MonoBehaviour
public Animator anim;
public Attack attack;
public float explodeTime = 0.5f;
private int explodeStopwatchID;
private bool explodeQueued;
private Vector2 explodePosition;
private int pelletCount = 16;
private EarthPellet currentEP;
public static GameObject Prefab => prefab ?? (prefab = ChaosBundle.Get("Assets/Prefabs/AreaEffects/EarthClap.prefab"));
private void Awake()
sec0Trans = transform.Find("LeftHand/Section0Sprite");
sec1Trans = transform.Find("LeftHand/Section1Sprite");
sec2Trans = transform.Find("LeftHand/Section2Sprite");
tipTrans = transform.Find("LeftHand/TipSprite");
anim = GetComponent<Animator>();
attack = transform.Find("LeftHand/LeftAttackBox").GetComponent<Attack>();
pSysSettings = new ParticleSystemOverride();
pSysSettings.startSpeed = -18f;
pSysSettings.radius = 4f;
pSysSettings.startLifetime = 0.25f;
impactTrans = transform.Find("LeftHand/ImpactLocation");
private void Start()
ParticleEffect poolItem = PoolManager.GetPoolItem<ParticleEffect>("RockFormEffect");
float? emissionRate = 15f;
ParticleSystemOverride overrides = pSysSettings;
poolItem.Play(emissionRate, null, overrides, 0.35f, sec0Trans);
ParticleEffect poolItem2 = PoolManager.GetPoolItem<ParticleEffect>("RockFormEffect");
emissionRate = 20f;
overrides = pSysSettings;
poolItem2.Play(emissionRate, null, overrides, 0.35f, sec1Trans);
ParticleEffect poolItem3 = PoolManager.GetPoolItem<ParticleEffect>("RockFormEffect");
emissionRate = 25f;
overrides = pSysSettings;
poolItem3.Play(emissionRate, null, overrides, 0.35f, sec2Trans);
ParticleEffect poolItem4 = PoolManager.GetPoolItem<ParticleEffect>("RockFormEffect");
emissionRate = 30f;
overrides = pSysSettings;
poolItem4.Play(emissionRate, null, overrides, 0.35f, tipTrans);
private void Update()
if (explodeQueued && ChaosStopwatch.Check(explodeStopwatchID))
PelletExplosion();
public void SetAttack(string skillCat, string skillID, Vector2 kbOverride)
attack.SetAttackInfo(skillCat, skillID);
attack.knockbackOverwriteVector = kbOverride;
public void OnDestroy()
RockDebrisEmitter poolItem = PoolManager.GetPoolItem<RockDebrisEmitter>();
if (!(poolItem == null))
poolItem.EmitSingle(10, sec0Trans.position);
poolItem.EmitSingle(10, sec1Trans.position);
poolItem.EmitSingle(10, sec2Trans.position);
poolItem.EmitSingle(10, tipTrans.position);
public void OnImpact()
PoolManager.GetPoolItem<RockMedDebrisEmitter>().EmitSingle(20, transform.position, RockMedDebrisEmitter.CircleExplosionOverride);
Vector2 vector = impactTrans.position;
if (Globals.CheckCircle(vector, 0.25f, ChaosCollisions.layerAll))
PoolManager.GetPoolItem<FloorCrackEmitter>().Emit(1, vector);
DustEmitter poolItem = PoolManager.GetPoolItem<DustEmitter>();
int particleCount = 50;
float scale = 0.25f;
float startSpeed = 10f;
Vector3? emitPosition = tipTrans.position;
poolItem.EmitCircle(particleCount, scale, startSpeed, -1f, emitPosition);
PoolManager.GetPoolItem<ParticleEffect>("FloorCraterLarge").Emit(1, vector);
string audioID = "EarthExplosion";
Vector2? soundOrigin = vector;
startSpeed = Random.Range(0.9f, 1.1f);
SoundManager.PlayAudioWithDistance(audioID, soundOrigin, null, 24f, -1f, startSpeed);
explodeStopwatchID = ChaosStopwatch.Begin(explodeTime);
explodeQueued = true;
audioID = "Draw";
Vector3 position = tipTrans.position;
GameObject parentObj = tipTrans.gameObject;
Color? color = CastingCircle.enemyColor;
startSpeed = explodeTime;
CastingCirclePool.Spawn(audioID, position, disableWithParentVal: true, parentObj, trackParentVal: true, useCastTimeVal: false, 0f, 4f, 4f, color, startSpeed);
public void PelletExplosion()
attack.ChangeAttackInfoLevel(2);
explodePosition = impactTrans.position;
for (int i = 0; i < pelletCount; i++)
CreateEarthPellet(explodePosition, Globals.GetCirclePositionVector(pelletCount, i));
PoolManager.GetPoolItem<RockDebrisEmitter>().EmitSingle(50, explodePosition, RockDebrisEmitter.CircleExplosionOverride);
DustEmitter poolItem = PoolManager.GetPoolItem<DustEmitter>();
int particleCount = 100;
Vector3? emitPosition = explodePosition;
poolItem.EmitCircle(particleCount, 1f, -1f, -1f, emitPosition);
string audioID = "ShatterStone";
Vector2? soundOrigin = explodePosition;
float standardPitchRange = SoundManager.StandardPitchRange;
SoundManager.PlayAudioWithDistance(audioID, soundOrigin, null, 24f, -1f, standardPitchRange);
CameraController.ShakeCamera(0.4f);
Object.Destroy(gameObject);
private void CreateEarthPellet(Vector2 givenLocation, Vector2 givenVector)
currentEP = Globals.ChaosInst<EarthPellet>(EarthPellet.Prefab, transform.parent, givenLocation);
currentEP.attackBox.SetAttackInfo(attack.atkInfo);
currentEP.attackBox.knockbackOverwriteVector = givenVector;
currentEP.moveVector = givenVector;
currentEP.moveSpeed = 30f;
currentEP.flyTime = 0.125f;
=== EarthDrill
public class EarthDrill : MonoBehaviour
private RockDebrisEmitter rockDebrisEffect;
public Rigidbody2D rigidbody2D;
public Animator anim;
public Attack attack;
public SortSpriteLayer spriteSorter;
public Transform followTransform;
public Vector3 followOffset;
private AudioSource drillAudio;
public bool hitIntervalRunning;
private int hitStopwatchID;
public int hitCount = 5;
public float hitInterval = 0.125f;
public bool isMega;
public static GameObject Prefab => prefab ?? (prefab = ChaosBundle.Get("Assets/Prefabs/AreaEffects/EarthDrill.prefab"));
public static ParticleSystemOverride DebrisEffectSettings
get
if (_debrisEffectSettings == null)
_debrisEffectSettings = new ParticleSystemOverride();
_debrisEffectSettings.radius = 1.5f;
_debrisEffectSettings.startLifetime = 0.6f;
_debrisEffectSettings.startSpeed = 7f;
_debrisEffectSettings.emissionRate = 20f;
return _debrisEffectSettings;
public static ParticleSystemOverride MegaDebrisEffectSettings
get
if (_megaDebrisEffectSettings == null)
_megaDebrisEffectSettings = new ParticleSystemOverride();
_megaDebrisEffectSettings.radius = 2.25f;
_megaDebrisEffectSettings.startLifetime = 0.6f;
_megaDebrisEffectSettings.startSpeed = 8f;
_megaDebrisEffectSettings.emissionRate = 28f;
return _megaDebrisEffectSettings;
public void Awake()
anim = GetComponent<Animator>();
rigidbody2D = GetComponent<Rigidbody2D>();
attack = transform.Find("AttackBox").GetComponent<Attack>();
spriteSorter = transform.Find("Sprite").GetComponent<SortSpriteLayer>();
public void Start()
if (isMega)
anim.Play("MegaSpawn", -1, 0f);
PoolManager.GetPoolItem<ParticleEffect>("RockFormEffect").Emit(24, transform.position + followOffset * 0.75f, RockFormEffect.MedSettings);
rockDebrisEffect = PoolManager.GetPoolItem<RockDebrisEmitter>();
rockDebrisEffect.PlaySingle(7f, transform.position, MegaDebrisEffectSettings, followTransform: transform, playTime: 5f);
else
anim.Play("Spawn", -1, 0f);
PoolManager.GetPoolItem<ParticleEffect>("RockFormEffect").Emit(10, transform.position, RockFormEffect.MedSettings);
rockDebrisEffect = PoolManager.GetPoolItem<RockDebrisEmitter>();
rockDebrisEffect.PlaySingle(5f, transform.position, DebrisEffectSettings, followTransform: transform, playTime: 5f);
if (drillAudio == null || !drillAudio.isPlaying)
drillAudio = SoundManager.PlayAudioWithDistance("Drill", transform.position);
public void Activate()
if (isMega)
anim.Play("MegaSpin", -1, 0f);
else
anim.Play("Spin", -1, 0f);
public void Deactivate()
if (isMega)
anim.Play("MegaIdle", -1, 0f);
else
anim.Play("Idle", -1, 0f);
if (rockDebrisEffect != null)
rockDebrisEffect.Stop();
public void StartInterval()
hitIntervalRunning = true;
hitStopwatchID = ChaosStopwatch.Begin(hitInterval, useInterval: true, hitInterval, hitCount);
private void FixedUpdate()
if (followTransform != null)
transform.position = followTransform.position + followOffset;
if (hitIntervalRunning)
switch (ChaosStopwatch.CheckInterval(hitStopwatchID))
case StopwatchState.Running:
attack.gameObject.SetActive(value: true);
break;
case StopwatchState.Ready:
attack.gameObject.SetActive(value: false);
break;
case StopwatchState.Done:
Deactivate();
hitIntervalRunning = false;
attack.gameObject.SetActive(value: true);
break;
public void Reset()
Vector3 vector;
if (isMega)
vector = transform.position + followOffset * 0.25f;
PoolManager.GetPoolItem<RockDebrisEmitter>().EmitSingle(8, vector, RockDebrisEmitter.MedCircleExplosionOverride);
PoolManager.GetPoolItem<RockMedDebrisEmitter>().EmitSingle(6, vector, RockDebrisEmitter.MedCircleExplosionOverride);
PoolManager.GetPoolItem<RockMedDebrisEmitter>().EmitSingle(4, vector, RockDebrisEmitter.MedCircleExplosionOverride);
else
vector = transform.position + spriteSorter.transform.TransformPoint(Vector3.up).normalized;
PoolManager.GetPoolItem<RockDebrisEmitter>().EmitSingle(6, vector, RockDebrisEmitter.SmallCircleSlowExplosionOverride);
PoolManager.GetPoolItem<RockMedDebrisEmitter>().EmitSingle(4, vector, RockDebrisEmitter.SmallCircleExplosionOverride);
PoolManager.GetPoolItem<RockMedDebrisEmitter>().EmitSingle(1, vector, RockDebrisEmitter.SmallCircleExplosionOverride);
Deactivate();
if (drillAudio != null && drillAudio.isPlaying)
drillAudio.Stop();
SoundManager.PlayAudioWithDistance("EarthPebble", vector);
SoundManager.PlayAudioWithDistance("RockExplode", vector);
DustEmitter poolItem = PoolManager.GetPoolItem<DustEmitter>();
int particleCount = 4;
Vector3? emitPosition = transform.position;
poolItem.EmitDirBurst(particleCount, 0f, -1f, -1f, -1f, emitPosition);
if (rockDebrisEffect != null)
rockDebrisEffect.Stop();
Object.Destroy(gameObject);
public void PlayFormAudio()
string audioID = "RockFormShort";
Vector2? soundOrigin = transform.position;
float standardPitchRange = SoundManager.StandardPitchRange;
SoundManager.PlayAudioWithDistance(audioID, soundOrigin, null, 24f, -1f, standardPitchRange);

